# Pinecrest: by stagecoach. Snow all year (main.c forces the winter palette). Long nights: preserves and hot dishes sell best.
map PINECREST set=FARM w=16 h=14 music=SNOWY
key # FOREST block
key P PINE block
key . GRASS walk
key , GRASS2 walk
key = PATH walk
key r ROCK block
key l LOG block
key s STUMP block
key x MINE_CRATE block
key L LAMP block
grid
